"use client";

import { motion, useReducedMotion } from "framer-motion";
import { Bismillah } from "@/components/decorative/Arabic";
import { CoverBotanicals, PaperGrain } from "@/components/decorative/Ornaments";
import { Monogram } from "@/components/decorative/Monogram";
import { OpeningAnimation } from "@/components/invitation/OpeningAnimation";
import { coupleNames, monogramMarks, personName, wedding } from "@/config/wedding";
import { useInvitation } from "@/context/InvitationContext";

export function InvitationCover() {
  const { isOpen, isOpening, openInvitation } = useInvitation();
  const reduce = useReducedMotion();
  const dateLine = wedding.date.display.coverLine;
  const mark = monogramMarks();

  return (
    <OpeningAnimation show={!isOpen} opening={isOpening}>
      <div className="cover-inner">
        <PaperGrain />
        <CoverBotanicals />
        <div className="cover-content">
          <motion.div
            animate={isOpening && !reduce ? { opacity: 0 } : { opacity: 1 }}
            transition={{ duration: 0.4, ease: "easeOut" }}
          >
            <Bismillah />
          </motion.div>

          <Monogram
            initialOne={mark.one}
            initialTwo={mark.two}
            joiner={mark.joiner}
            size="md"
          />

          <div className="cover-names">
            <p className="cover-name">{personName(wedding.couple.person1)}</p>
            <span className="cover-and">{wedding.couple.monogramJoiner}</span>
            <p className="cover-name">{personName(wedding.couple.person2)}</p>
          </div>

          <p className="cover-together">{wedding.copy.togetherWithFamilies}</p>
          <p className="cover-date">{dateLine}</p>

          <motion.button
            type="button"
            className="cover-open"
            onClick={openInvitation}
            animate={isOpening && !reduce ? { opacity: 0, y: 10 } : { opacity: 1, y: 0 }}
            transition={{ duration: 0.35, ease: "easeOut" }}
          >
            {wedding.copy.openInvitation}
          </motion.button>
          <p className="cover-hint">Tap to open</p>
          <span className="visually-hidden">{coupleNames()}</span>
        </div>
      </div>
    </OpeningAnimation>
  );
}
